MIN_ROWS = 500       # below this, PSI is mostly noise (see --noise)
PAGE_PSI = 0.25      # an input the model relies on has clearly moved
TICKET_PSI = 0.10    # worth a look in working hours
LABEL_Z = 4.0        # the late rate is this many standard errors from what the model expects...
LABEL_GAP = 0.02     # ...and at least this far away in absolute terms


def decide(window):
    """Return (action, reasons). PAGE wakes someone, ticket waits for the morning, log is only recorded."""
    if window["rows"] < MIN_ROWS:
        return "wait", [f"only {window['rows']} rows, too few to judge"]
    page, ticket, log = [], [], []
    for feature, value in window["psi"].items():
        text = f"PSI {value:.2f} on {feature}"
        if not window["used"][feature]:
            if value > TICKET_PSI:
                log.append(text + " (the model does not use it)")
        elif value > PAGE_PSI:
            page.append(text)
        elif value > TICKET_PSI:
            ticket.append(text)
    if window["z"] is not None and abs(window["z"]) > LABEL_Z and abs(window["gap"]) > LABEL_GAP:
        ticket.append(f"late rate {window['gap']:+.3f} from what the model expects (z {window['z']:+.1f})")
    for action, reasons in (("PAGE", page), ("ticket", ticket), ("log", log)):
        if reasons:
            return action, reasons
    return "ok", []
